'use client';
import React,{useState} from 'react';
import type {RecordRow as R,State} from '@/lib/erp-primitives';
import {day} from '@/lib/erp-primitives';
import {classifications,documentKinds,knowledgeCategories,documentUsable,knowledgeUsable} from '@/lib/governance';
export function GovernanceFields({type,form,records,update}:{type:string;form:any;records:R[];update:(key:string,value:any)=>void}){
const field=(label:string,key:string,kind='text',required=false)=><label>{label}<input type={kind} required={required} value={form[key]||''} onChange={e=>update(key,e.target.value)}/></label>;
const select=(label:string,key:string,options:string[])=><label>{label}<select value={form[key]||options[0]} onChange={e=>update(key,e.target.value)}>{options.map(v=><option key={v}>{v}</option>)}</select></label>;
return <>{field('Record owner','owner','text',true)}{field('Next review date','reviewDue','date',true)}{type==='document'?<>{field('Document ID, leave blank to generate','documentCode')}{select('Document type','documentKind',documentKinds)}{select('Classification','classification',classifications)}{field('Revision, for example 1.0','revisionLabel','text',true)}{field('Source or file reference','sourceRef','text',true)}{field('Document link, if available','sourceUrl','url')}<label className="fullwidth">Document summary<textarea rows={4} value={form.summary||''} onChange={e=>update('summary',e.target.value)}/></label><p className="fullwidth notice">This register stores references and links to your files. Verify the actual source document before approving its record.</p></>:<>{select('Knowledge category','category',knowledgeCategories)}<label className="fullwidth">Knowledge statement<textarea required rows={5} value={form.statement||''} onChange={e=>update('statement',e.target.value)}/></label><label>Source document<select value={form.sourceDocumentId||''} onChange={e=>update('sourceDocumentId',e.target.value)}><option value="">Choose a document</option>{records.filter(r=>r.company===form.company&&r.type==='document').map(r=><option value={r.id} key={r.id}>{r.documentCode} · {r.name} · {r.status}</option>)}</select></label><label className="officepermission fullwidth"><input type="checkbox" checked={form.externalUseAllowed===true} onChange={e=>update('externalUseAllowed',e.target.checked)}/>Approved for external use after verification</label><p className="fullwidth notice">A verified statement requires a current verified source document. Source changes or expired reviews make the statement need review.</p></>}</>;
}
export default function Governance({state,company,kind,open,create,act,busy,initialSelected=''}:{state:State;company:string;kind:'document'|'knowledge';open:(type:string,r?:R)=>void;create:(type:string,seed:any)=>void;act:(x:any)=>Promise<void>;busy:boolean;initialSelected?:string}){
const [query,setQuery]=useState(''),[status,setStatus]=useState('All'),[selected,setSelected]=useState(initialSelected);
const records=state.records.filter(r=>r.type===kind&&(company==='Group'||r.company===company)),usable=(r:R)=>kind==='document'?documentUsable(r,day()):knowledgeUsable(r,state.records,day()),shown=records.filter(r=>(status==='All'||status==='Needs review'?status==='All'||r.status==='Verified'&&!usable(r):r.status===status)&&[r.name,r.documentCode,r.statement,r.owner,r.sourceRef].join(' ').toLowerCase().includes(query.toLowerCase())),r=records.find(x=>x.id===selected),source=r&&state.records.find(x=>x.id===r.sourceDocumentId&&x.company===r.company),title=kind==='document'?'Documents':'Knowledge records';
return <><div className="sectiontoolbar"><label className="searchbox">Search {title.toLowerCase()}<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Name, owner or reference"/></label><label className="projectfilter">Show<select value={status} onChange={e=>setStatus(e.target.value)}>{['All','Draft','Review','Verified','Needs review','Historical'].map(v=><option key={v}>{v}</option>)}</select></label><button className="primary" onClick={()=>create(kind,{company:company==='Group'?'Hagadol':company})}>Add {kind==='document'?'document':'knowledge record'}</button></div><p className="notice">{kind==='document'?'Keep source references, file links, revisions, classifications and review dates in one register.':'Record company facts with source evidence and a named reviewer. Unverified examples are never inserted automatically.'} Restricted documents remain within this private owner workspace.</p><div className="tablebox"><table className="technicaltable"><thead><tr><th>{title}</th><th>Company</th><th>Owner</th><th>Review due</th><th>Status</th></tr></thead><tbody>{shown.map(x=><tr key={x.id}><td><button className="rowlink" onClick={()=>setSelected(x.id)}><strong>{x.name}</strong><small>{kind==='document'?x.documentCode:x.category}</small></button></td><td>{x.company}</td><td>{x.owner}</td><td>{x.reviewDue||'Not set'}</td><td>{x.status==='Verified'&&!usable(x)?'Needs review':x.status}</td></tr>)}</tbody></table>{!shown.length&&<p className="empty">No {title.toLowerCase()} match this view.</p>}</div>{r&&<section className="panel governancedetail"><header className="panelhead"><div><small>{r.company} · {r.documentCode||r.category}</small><h2>{r.name}</h2><p>{r.status==='Verified'&&!usable(r)?'Needs review':r.status}</p></div></header><dl className="detaildl"><dt>Owner</dt><dd>{r.owner}</dd><dt>Review due</dt><dd>{r.reviewDue}</dd>{kind==='document'?<><dt>Classification</dt><dd>{r.classification}</dd><dt>Document type</dt><dd>{r.documentKind}</dd><dt>Revision</dt><dd>{r.revisionLabel}</dd><dt>Source reference</dt><dd>{r.sourceRef}</dd></>:<><dt>Source document</dt><dd>{source?.documentCode||'Not linked'} · {source?.name}</dd><dt>Current source revision</dt><dd>{source?.revisionLabel||'Not recorded'} · Version {source?.version??'Not recorded'} · {source?.status||'Missing'}</dd><dt>Source version checked</dt><dd>{r.sourceDocumentVersion??'Not verified'}</dd><dt>External use</dt><dd>{r.externalUseAllowed&&usable(r)?'Permitted for this verified statement':'Internal review only'}</dd></>}{r.verifiedBy&&<><dt>Verified by</dt><dd>{r.verifiedBy}</dd><dt>Verified at</dt><dd>{r.verifiedAt}</dd></>}</dl><p className="detailnotes">{r.summary||r.statement}</p>{r.sourceUrl&&<a className="secondary" href={r.sourceUrl} target="_blank" rel="noreferrer">Open source document</a>}{r.previousDocumentId&&<p>Previous revision: {state.records.find(x=>x.id===r.previousDocumentId&&x.company===r.company)?.documentCode||r.previousDocumentId}</p>}<div className="recordactions">{['Draft','Review'].includes(r.status)&&<button className="secondary" disabled={busy} onClick={()=>open(kind,r)}>Edit record</button>}{r.status==='Draft'&&<button className="primary" disabled={busy} onClick={()=>act({action:'stage',id:r.id,expectedVersion:r.version,status:'Review'})}>Move to Review</button>}{r.status==='Review'&&<button className="primary" disabled={busy} onClick={()=>{if(window.confirm('Confirm you reviewed the actual source and this record is accurate.'))act({action:'stage',id:r.id,expectedVersion:r.version,sourceExpectedVersion:source?.version,status:'Verified'})}}>Verify record</button>}{['Verified','Historical','Review'].includes(r.status)&&<button className="secondary" disabled={busy} onClick={()=>act({action:'stage',id:r.id,expectedVersion:r.version,status:'Draft'})}>Return to Draft</button>}{r.status==='Verified'&&<button className="secondary" disabled={busy} onClick={()=>act({action:'stage',id:r.id,expectedVersion:r.version,status:'Historical'})}>Archive as Historical</button>}{kind==='document'&&<button className="secondary" onClick={()=>create('document',{company:r.company,name:r.name,previousDocumentId:r.id,projectId:r.projectId,documentKind:r.documentKind,classification:r.classification,revisionLabel:'',sourceRef:r.sourceRef,sourceUrl:r.sourceUrl,owner:r.owner,reviewDue:r.reviewDue,summary:r.summary})}>Create revision</button>}</div></section>}</>;
}
